class Solution:
    def constructProductMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n, m = len(grid), len(grid[0])
        total_elements = n * m

        # Flatten the grid into a 1D array
        flat_grid = []
        for i in range(n):
            for j in range(m):
                flat_grid.append(grid[i][j])

        # Calculate prefix products
        prefix = [1] * total_elements
        for i in range(1, total_elements):
            prefix[i] = (prefix[i-1] * flat_grid[i-1]) % 12345

        # Calculate suffix products
        suffix = [1] * total_elements
        for i in range(total_elements-2, -1, -1):
            suffix[i] = (suffix[i+1] * flat_grid[i+1]) % 12345

        # Construct result matrix
        result = [[0] * m for _ in range(n)]

        for i in range(n):
            for j in range(m):
                idx = i * m + j
                # Product excluding flat_grid[idx] = prefix[idx] * suffix[idx]
                result[i][j] = (prefix[idx] * suffix[idx]) % 12345

        return result

