from itertools import combinations
from collections import defaultdict

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px, py = find(parent, x), find(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        px, py = py, px
    parent[py] = px
    if rank[px] == rank[py]:
        rank[px] += 1
    return True

def is_spanning_tree(edges, n):
    if len(edges) != n - 1:
        return False

    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    for u, v, w in edges:
        if not union(parent, rank, u, v):
            return False

    # Check if all vertices are connected (should have one component)
    root = find(parent, 1)
    for i in range(2, n + 1):
        if find(parent, i) != root:
            return False

    return True

