class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        import bisect

        n = len(nums)
        min_diff = float('inf')

        sorted_values = []

        for j in range(n):
            if j >= x:
                pos = bisect.bisect_left(sorted_values, nums[j])
                if pos < len(sorted_values):
                    min_diff = min(min_diff, abs(nums[j] - sorted_values[pos]))
                if pos > 0:
                    min_diff = min(min_diff, abs(nums[j] - sorted_values[pos-1]))

            bisect.insort(sorted_values, nums[j])

        return min_diff

