class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        from bisect import bisect_left

        n = len(nums)
        min_diff = float('inf')

        # Maintain sorted list of values from positions [0, i-x]
        sorted_values = []

        for i in range(n):
            # Add nums[i-x] to sorted_values first (available for pairing with nums[i])
            if i >= x:
                bisect.insort(sorted_values, nums[i - x])

            # Now check if we can pair nums[i] with any element in sorted_values
            if i >= x:
                pos = bisect_left(sorted_values, nums[i])
                if pos > 0:
                    min_diff = min(min_diff, abs(nums[i] - sorted_values[pos - 1]))
                if pos < len(sorted_values):
                    min_diff = min(min_diff, abs(nums[i] - sorted_values[pos]))

        return min_diff

class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        from bisect import insort

        n = len(nums)
        if n <= 1:
            return 0

        min_diff = float('inf')
        # We'll maintain a sorted list of elements from indices [0, i-x]
        left_elements = []

        for i in range(n):
            # When i >= x, we can pair nums[i] with elements at indices <= i-x
            if i >= x:
                # Binary search to find insertion point
                pos = self.binary_search(left_elements, nums[i])

                # Check the element at pos
                if pos < len(left_elements):
                    min_diff = min(min_diff, abs(nums[i] - left_elements[pos]))

                # Check the element at pos-1
                if pos > 0:
                    min_diff = min(min_diff, abs(nums[i] - left_elements[pos-1]))

            # Add current element to left_elements for future use
            insort(left_elements, nums[i])

        return min_diff if min_diff != float('inf') else 0

    def binary_search(self, arr, target):
        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        n = len(nums)
        min_diff = float('inf')

        # For each pair of indices that are at least x apart
        for i in range(n):
            for j in range(n):
                if abs(i - j) >= x:
                    min_diff = min(min_diff, abs(nums[i] - nums[j]))

        return min_diff
